const helperItems = $('helper').all();

// Token limit is based on the API being used (LLM limitations)
const TOKEN_LIMIT_PER_BATCH = 2000000;
const CHARS_PER_TOKEN = 4; // Approximatly
const MAX_CHARS_PER_BATCH = TOKEN_LIMIT_PER_BATCH * CHARS_PER_TOKEN;

// If a single file exceeds this, splitting it with 5% overlap
const MAX_CHARS_PER_FILE = MAX_CHARS_PER_BATCH;
const OVERLAP_CHARS = Math.floor(MAX_CHARS_PER_FILE * 0.05);


// Normalise all files into fragments 
const fragments = [];
helperItems.forEach((item) => {
  const text = typeof item.json.fileContent === 'string'
    ? item.json.fileContent
    : JSON.stringify(item.json.fileContent || '');
  const fileName = item.json.fileName || 'Unknown Document';
  if (!text.trim()) return;
  const estimatedTokens = Math.ceil(text.length / CHARS_PER_TOKEN);
  if (estimatedTokens <= TOKEN_LIMIT_PER_BATCH) {
    fragments.push({ fileName, content: text, estimatedTokens });
  } else {

    // File too large; split it and label each chunk with its origin
    const chunks = [];
    let start = 0;
    while (start < text.length) {
      let end = start + MAX_CHARS_PER_FILE;
      if (end < text.length) {
        const nearestSpace = text.lastIndexOf(' ', end);
        if (nearestSpace > start) end = nearestSpace;
      }
      const chunkText = text.slice(start, end).trim();
      if (chunkText.length > 0) chunks.push(chunkText);
      start = end - OVERLAP_CHARS;
      const nextSpace = text.indexOf(' ', start);
      if (nextSpace !== -1 && nextSpace < end) start = nextSpace + 1;
    }
    chunks.forEach((chunkText, i) => {
      fragments.push({
        fileName: `${fileName} (part ${i + 1}/${chunks.length})`,
        content: chunkText,
        estimatedTokens: Math.ceil(chunkText.length / CHARS_PER_TOKEN)
      });
    });
  }
});

const batches = [];
let currentBatch = [];
let currentBatchTokens = 0;
fragments.forEach((fragment) => {
  const willExceed = currentBatchTokens + fragment.estimatedTokens > TOKEN_LIMIT_PER_BATCH;
  if (willExceed && currentBatch.length > 0) {
    batches.push({ files: currentBatch, totalTokens: currentBatchTokens });
    currentBatch = [];
    currentBatchTokens = 0;
  }
  currentBatch.push(fragment);
  currentBatchTokens += fragment.estimatedTokens;
});
if (currentBatch.length > 0) {
  batches.push({ files: currentBatch, totalTokens: currentBatchTokens });
}

// Output one item per batch
const results = [];
const totalBatches = batches.length;
batches.forEach((batch, batchIndex) => {
  results.push({
    json: {
      batch_index: batchIndex + 1,
      total_batches: totalBatches,
      file_count: batch.files.length,
      estimated_tokens: batch.totalTokens,
      files: batch.files.map(f => ({
        fileName: f.fileName,
        content: f.content,
        estimated_tokens: f.estimatedTokens
      }))
    }
  });
});
return results;

