  let note = '';

  if (
    fileNameLower.endsWith('.csv') ||
    fileNameLower.endsWith('.xls') ||
    fileNameLower.endsWith('.xlsx')
  ) {
    if (Array.isArray(rawContent)) {
      const rows = rawContent.slice(0, MAX_ROWS);
      if (rawContent.length > MAX_ROWS)
        note = `[Preview: first ${MAX_ROWS} of ${rawContent.length} rows]`;
      text = JSON.stringify(rows);
    } else {
      text = typeof rawContent === 'string' ? rawContent : JSON.stringify(rawContent || '');
    }
  } else {
    const full = typeof rawContent === 'string'
      ? rawContent
      : JSON.stringify(rawContent || '');

    if (full.length > PREVIEW_CHARS_THRESHOLD) {
      // For large files, take 25% but never exceed MAX_PREVIEW_CHARS to stay within batch limit
      const previewChars = Math.min(Math.floor(full.length * 0.25), MAX_PREVIEW_CHARS);
      text = full.slice(0, previewChars);
      const lastSpace = text.lastIndexOf(' ');
      if (lastSpace > 0) text = text.slice(0, lastSpace);
      note = `[Preview: first 25% of document]`;
    } else {
      text = full;
    }
  }

  if (!text.trim()) return;
  if (note) text = `${note}\n\n${text}`;

  fragments.push({
    fileName,
    content: text,
    estimatedTokens: Math.ceil(text.length / CHARS_PER_TOKEN)
  });
});

