let currentBatchTokens = 0;

fragments.forEach((fragment) => {
  const willExceed = currentBatchTokens + fragment.json.estimated_tokens > TOKEN_LIMIT_PER_BATCH;
  if (willExceed && currentBatch.length > 0) {
    batches.push({ files: currentBatch, totalTokens: currentBatchTokens });
    currentBatch = [];
    currentBatchTokens = 0;
  }
  currentBatch.push(fragment.json);
  currentBatchTokens += fragment.json.estimated_tokens;
});

if (currentBatch.length > 0) {
  batches.push({ files: currentBatch, totalTokens: currentBatchTokens });
}

return batches.map((batch, i) => ({
  json: {
    batch_index: i + 1,
    total_batches: batches.length,
    file_count: batch.files.length,
    estimated_tokens: batch.totalTokens,
