const items = $input.all();

function flatten(obj, depth = 0) {
  if (obj === null || obj === undefined) return '';
  if (typeof obj !== 'object') return String(obj);
  const indent = '  '.repeat(depth);
  if (Array.isArray(obj)) {
    return obj.map((item, i) => {
      if (typeof item === 'object') {
        const fields = Object.entries(item)
          .filter(([_, v]) => v !== null && v !== undefined)
          .map(([k, v]) => `${k}: ${v}`)
          .join(' | ');
        return `${indent}${i + 1}. ${fields}`;
      }
      return `${indent}${i + 1}. ${item}`;
    }).join('\n');
  }
  return Object.entries(obj)
    .filter(([_, v]) => v !== null && v !== undefined && v !== '')
    .map(([k, v]) => {
      const label = k.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
      if (typeof v === 'object') {
        return `${indent}**${label}:**\n${flatten(v, depth + 1)}`;
      }
      return `${indent}- **${label}:** ${v}`;
    }).join('\n');
}

function extractObjects(text) {
  const results = [];

  // Try full parse
  try {
    const cleaned = text.replace(/```json|```/g, '').trim();
    const data = JSON.parse(cleaned);
    return Array.isArray(data) ? data : [data];
  } catch (e) { /* Failed */ }

  // Extract individual complete top-level objects
  let depth = 0, start = -1;
  for (let i = 0; i < text.length; i++) {
    if (text[i] === '{') {
      if (depth === 0) start = i;
      depth++;
    } else if (text[i] === '}') {
      depth--;
      if (depth === 0 && start !== -1) {
        try {
          const obj = JSON.parse(text.slice(start, i + 1));
          if (obj?.filename) results.push(obj);
        } catch (e) { /* skip */ }
        start = -1;
      }
    }
  }
  return results;
}

const parsed = items.flatMap(item => {
  const text = item.json.output?.text || item.json.text || item.json.output || '';

  const objects = extractObjects(text);
  if (objects.length === 0) return [];

  return objects.map(d => {
    let output = `## ${d.filename}\n###### Type: ${d.document_type}\n\n`;
    output += flatten(d.extracted_data || {});
    if (d.notes) output += `\n\n**Notes:** ${d.notes}`;
    return output;
  });
}).join('\n\n---\n\n');

return [{ json: { message: parsed } }];

const mammoth = require('mammoth');

const items = $input.all();
const results = [];

for (const item of items) {
  const binary = item.binary || {};
  const binaryKey = Object.keys(binary)[0];

  if (!binaryKey) continue;

  const fileName = binary[binaryKey]?.fileName || 'Unknown.docx';
  const buffer = await this.helpers.getBinaryDataBuffer(
    items.indexOf(item), 
    binaryKey
  );

  try {
    const result = await mammoth.extractRawText({ buffer });

    results.push({
      json: {
        fileName: fileName,
        fileContent: result.value
      },
      binary: {
        data: binary[binaryKey]
      }
    });
  } catch (err) {
    results.push({
      json: {
        fileName: fileName,
        fileContent: '',
        error: err.message
      }
    });
  }
}

return results;

